import{_ as t}from"./chunks/mixed.D5USwrGH.js";import{_ as a,o as s,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"À propos","description":"","frontmatter":{"title":"À propos"},"headers":[],"relativePath":"fr/projects/uix/index.md","filePath":"fr/projects/uix/index.md","lastUpdated":1793447386000}'),i={name:"fr/projects/uix/index.md"};function n(l,e,u,d,c,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ui-extension-pour-home-assistant" tabindex="-1">UI eXtension pour Home Assistant <a class="header-anchor" href="#ui-extension-pour-home-assistant" aria-label="Permalink to &quot;UI eXtension pour Home Assistant&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">État vérifié le 31 octobre 2026</p><p>Base stable : <strong>UIX 8.4.0</strong>, nécessite <strong>Home Assistant 2026.10.0 ou ultérieur</strong>. Les <strong>65</strong> pages sources anglaises ont été comparées à la révision <code>dev</code> <strong>e6fb84d / 9.0.0-beta.6</strong> ; DE/FR ont été complétées avec les changements. Les fonctions d’aperçu sont indiquées séparément. Voir le <a href="./translation-status">rapport</a>.</p></div><blockquote><p><strong>Traduction indépendante</strong> — Cette documentation française est maintenue par UGSo Software et n&#39;est pas la documentation officielle du projet UIX. La documentation anglaise reste la référence. Base comparée à la version stable <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v8.4.0" target="_blank" rel="noreferrer"><code>UIX 8.4.0</code></a> du 7 octobre 2026, révision <a href="https://github.com/Lint-Free-Technology/uix/commit/71b8ccd38202257c070ae9970a7aac12a68a6389" target="_blank" rel="noreferrer"><code>71b8ccd</code></a>. <strong>Home Assistant 2026.10.0 ou ultérieur est requis.</strong></p></blockquote><p><img src="'+t+'" alt="light-logo-icon"></p><h2 id="qu-est-ce-que-ui-extension" tabindex="-1">Qu&#39;est-ce que UI eXtension ? <a class="header-anchor" href="#qu-est-ce-que-ui-extension" aria-label="Permalink to &quot;Qu&#39;est-ce que UI eXtension ?&quot;">​</a></h2><p>::: note Utilisateurs de Card-mod Si vous migrez depuis Card-mod, consultez la <a href="./faq">FAQ</a>, qui répond à la plupart des questions. Pour toute autre question, utilisez les <a href="https://github.com/Lint-Free-Technology/uix/discussions" target="_blank" rel="noreferrer">discussions GitHub</a>.</p><p>::: Avec un ensemble de fonctions qui dépasse les cartes et les tableaux de bord, UI eXtension (UIX) a été créé pour étendre les possibilités du CSS personnalisé dans l&#39;interface Home Assistant. UIX s&#39;inscrit dans la continuité de <a href="https://github.com/thomasloven/lovelace-card-mod" target="_blank" rel="noreferrer">card-mod</a>, créé par <a href="https://github.com/thomasloven" target="_blank" rel="noreferrer">@thomasloven</a>.</p><p>UI eXtension comprend <a href="./using/">UIX Styling</a>, <a href="./forge/">UIX Forge</a> et <a href="./broker/">UIX Broker</a>. <a href="./using/">UIX Styling</a> permet d&#39;appliquer du CSS à presque tous les éléments de l&#39;interface Home Assistant. <a href="./forge/">UIX Forge</a> permet de créer des éléments Home Assistant (cartes, badges, lignes, etc.) avec des modèles pour toute leur configuration et des extensions avancées grâce aux <a href="./forge/sparks/">Sparks UIX Forge</a>. UIX Broker transforme les événements du navigateur, les raccourcis clavier et les événements du bus Home Assistant en interactions déclaratives. Une interaction sélectionne un élément, vérifie des règles optionnelles, puis exécute ses directives dans l&#39;ordre configuré.</p><h2 id="nouveautes-de-uix-8-4-0" tabindex="-1">Nouveautés de UIX 8.4.0 <a class="header-anchor" href="#nouveautes-de-uix-8-4-0" aria-label="Permalink to &quot;Nouveautés de UIX 8.4.0&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Aperçu : UIX 9.0.0-beta.6</p><p>Les <a href="./using/custom-sidebar-panels">raccourcis personnalisés dans la barre latérale</a> sont disponibles à partir de <strong>9.0.0-beta.6</strong>. L’<a href="./forge/forge#visual-editor-cards-and-badges">éditeur visuel Forge</a>, disponible depuis <strong>9.0.0-beta.2</strong>, propose <strong>Convert to visual editor</strong> pour les Forges directes de carte ou de badge existantes. La base stable reste <strong>8.4.0</strong>.</p></div><ul><li><a href="./forge/sparks/form">Spark Formulaire</a> et <a href="./extras/uix-actions#popover">action Popover</a> pour les formulaires et les contenus superposés.</li><li><a href="./extras/style-frame-panels">Style des panneaux intégrés dans un frame</a> avec un runtime interne ; cette option expérimentale reste désactivée par défaut.</li><li><a href="./using/themes">Polices de thème avec <code>uix-fonts</code></a> et <a href="./using/images">images d&#39;entité dans les aperçus de carte</a>, avec adaptation à Home Assistant 2026.10.</li><li>Les <a href="./broker/directives#regles-de-la-directive">règles de directive Broker</a> peuvent utiliser les résultats de directives JavaScript ou template précédentes.</li></ul><p>Les ajouts précédemment décrits pour les versions bêta 8.4 font désormais partie de la version stable. Les mentions historiques indiquent toujours la version d&#39;introduction des fonctions.</p><h2 id="🚀-demarrage-rapide" tabindex="-1">🚀 Démarrage rapide <a class="header-anchor" href="#🚀-demarrage-rapide" aria-label="Permalink to &quot;🚀 Démarrage rapide&quot;">​</a></h2><p>Consultez le <a href="./quick-start">Démarrage rapide</a> pour l&#39;installation et un premier exemple de UIX Styling et UIX Forge.</p><h2 id="➡️-continuer" tabindex="-1">➡️ Continuer <a class="header-anchor" href="#➡️-continuer" aria-label="Permalink to &quot;➡️ Continuer&quot;">​</a></h2><ul><li><a href="./using/">Utiliser UIX Styling</a></li><li><a href="./forge/">Utiliser UIX Forge</a></li><li><a href="./faq">FAQ</a></li></ul>',16)])])}const h=a(i,[["render",n]]);export{f as __pageData,h as default};
